INSERT INTO public.quests(id,archived,content) VALUES ('q_snack_crawl',false,'{"id":"q_snack_crawl","title":"$5 Mystery Snack Draft","hook":"Everyone buys the one snack nobody can read the label of. Then you rank them blind.","mission":"United Noodles is a giant Asian grocery a 10-minute bike ride from West Bank. Everyone gets $5 and 15 minutes to find the strangest snack or drink in the store, and the group builds a tier list on the curb.","steps":["Bike over or take the 2 bus down Franklin to United Noodles (2015 E 24th St). It''s open 9am-8pm every day.","Everyone gets $5 and 15 minutes. Goal: a snack or drink nobody else in the group has ever seen.","Keep your pick hidden in your bag. Rock-paper-scissors sets the reveal order.","Taste everything outside or back at someone''s place and build an S-to-F tier list.","Whoever brought the lowest-ranked snack buys the next round."],"vibes":["food","weird","competitive","social"],"location":{"name":"United Noodles","area":"Seward","lat":44.95784,"lng":-93.2422},"durationMin":60,"costPerPerson":5,"groupMin":2,"groupMax":6,"weirdness":4,"adventure":2,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_stone_arch_freeze',false,'{"id":"q_stone_arch_freeze","title":"Stone Arch Freeze Frame","hook":"One group pose, three spots, one sunset: gold, then blue, then city lights.","mission":"Cross the Stone Arch Bridge at golden hour, loop through St. Anthony Main, and come back over the Hennepin Avenue Bridge after dark. You hit the exact same pose at three stops so the sky changes behind you.","steps":["Meet at the Mill District end of the Stone Arch Bridge about 20 minutes before sunset (around 7pm in late September, about 6:30 by mid-October). Agree on one group pose. You''re stuck with it.","Frame 1: middle of the bridge with St. Anthony Falls behind you.","Cross to the St. Anthony Main side. Frame 2 at Father Hennepin Bluff Park, falls and bridge in one shot, as the sky goes blue.","Walk up Main St to Hennepin Ave and start across the Hennepin Avenue Bridge. Frame 3: same pose with the lit-up Grain Belt sign behind you.","Post the three as one set. Anyone who broke the pose buys hot drinks."],"vibes":["outdoors","creative","chill","social"],"location":{"name":"Stone Arch Bridge","area":"Mill District / St. Anthony Main","lat":44.98074,"lng":-93.25361},"durationMin":75,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":2,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_midnight_photo_hunt',false,'{"id":"q_midnight_photo_hunt","title":"Blue Hour Photo Hunt","hook":"Six prompts, 35 minutes, no flash, and it gets darker every minute.","mission":"A photo scavenger hunt around the Mill District right as the lights come on. Work in pairs, argue about whether a shot really counts, then vote from the top of the Gold Medal Park hill.","steps":["Meet at Gold Medal Park at sunset (about 7pm in late September, closer to 5pm by November). Split into pairs.","Prompts: something glowing, a reflection, something way too tall, your own shadow looking cool, something older than 1900, and the Gold Medal Flour sign from an angle nobody else gets.","35 minutes on the clock. No flash. Stay between the Guthrie, the Stone Arch Bridge and Mill City Museum, on lit paths and sidewalks.","Regroup at the top of the park''s spiral hill and vote on the best shot for each prompt. Most wins picks dinner."],"vibes":["creative","competitive","outdoors","social"],"location":{"name":"Gold Medal Park","area":"Mill District / Downtown East","lat":44.97743,"lng":-93.25322},"durationMin":60,"costPerPerson":0,"groupMin":2,"groupMax":8,"weirdness":3,"adventure":3,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_global_market_draft',false,'{"id":"q_global_market_draft","title":"Midtown Global Market Draft","hook":"Snake-draft the food stalls like fantasy football. Lowest score buys dessert.","mission":"Midtown Global Market on Lake Street packs Somali, Nepali, Jamaican, Mexican, Cambodian-Thai and soul food stalls under one roof. Draft stalls like players, share everything at one table, and let the scores settle it.","steps":["Bike the Midtown Greenway (about 25 min), or take the Blue Line to Lake St/Midtown and the B Line west to Lake & Chicago. Your U Card covers both. It''s at 920 E Lake St, open Mon-Sat 10-8 and Sun 11-6, and some stalls close Sundays.","Snake draft, three rounds, $8 max per pick. Mains blow the cap (Irie''s jerk chicken is about $20), so hunt the small stuff: Irie''s $6 beef patty, egg rolls, a taco, a sambusa. A drafted stall is locked.","Put everything in the middle of one table and pass it around.","Everyone scores every dish 1-10. The drafter with the lowest total buys dessert."],"vibes":["food","competitive","social"],"location":{"name":"Midtown Global Market","area":"Phillips / Lake Street","lat":44.94876,"lng":-93.26075},"durationMin":90,"costPerPerson":22,"groupMin":3,"groupMax":6,"weirdness":2,"adventure":2,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_weisman_mimic',false,'{"id":"q_weisman_mimic","title":"Mimic the Weisman","hook":"Recreate a piece of art using only what''s in your backpacks.","mission":"The Weisman is the shiny steel museum on the river edge of campus, and it''s always free. Everyone secretly picks a work, stages a low-budget recreation, and the group guesses which piece it is.","steps":["Go Wed-Fri 10am-5pm or Sat-Sun 11am-5pm. It''s closed Mondays and Tuesdays.","Walk the galleries once. Everyone secretly picks one work.","20 minutes to recreate yours with backpack contents only. Shoot it outside against the steel walls.","Show each photo and the group guesses the original. Best guesser picks lunch."],"vibes":["creative","weird","chill"],"location":{"name":"Weisman Art Museum","area":"East Bank (campus)","lat":44.9734,"lng":-93.2372},"durationMin":60,"costPerPerson":0,"groupMin":2,"groupMax":5,"weirdness":4,"adventure":1,"bestTime":["morning","afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_minnehaha_descent',false,'{"id":"q_minnehaha_descent","title":"Falls to the River, Then Tacos","hook":"Follow the creek from the falls until you hit the Mississippi, then climb back up for fish tacos.","mission":"Minnehaha Falls is a 30-minute bike ride down the river from campus. Take the stairs to the bottom, follow the creek through the glen until it meets the Mississippi, then grab fish tacos at Sea Salt before it closes for the season in early October.","steps":["Bike south on West River Parkway (about 30 min), or take the Green Line to Downtown East and switch to the Blue Line to 50th St/Minnehaha Park. Your U Card covers it. From the station it''s a 5-minute walk.","Take the stone stairs down to the base of the falls and follow the creek trail downstream.","Keep going until you can see the big river. First person to spot the Mississippi picks the table.","Climb back up and order at Sea Salt. It''s seasonal: if it''s already closed, the hike is still free and still worth it.","Stay on the trails and never go behind the falls."],"vibes":["outdoors","active","food"],"location":{"name":"Minnehaha Falls","area":"Minnehaha / Longfellow","lat":44.91533,"lng":-93.21098},"durationMin":150,"costPerPerson":15,"groupMin":1,"groupMax":6,"weirdness":1,"adventure":3,"bestTime":["morning","afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_northeast_mural_bingo',false,'{"id":"q_northeast_mural_bingo","title":"Northeast $10 Art Hunt","hook":"350 artists, one old seed warehouse, and $10 to find the best thing in the building.","mission":"The Northrup King Building in Northeast is a huge former seed warehouse packed with artist studios, and on First Thursdays and Open Saturdays they open up. Everyone hunts for one small piece under $10 and pitches it to the group. The big weekend is Art Attack, Nov 13-15.","steps":["Go on First Thursday (next one is Oct 1, 4-8pm) or any Open Saturday (12-4pm). Bike about 15 minutes from Dinkytown to 1500 Jackson St NE.","Split up for 45 minutes. Everyone finds one thing under $10: a print, a sticker, a zine, a tiny ceramic.","Ask the artist one question about how they made it.","Regroup in the lobby. 30-second pitch each, then vote. The winning piece goes on someone''s wall.","Count every mural you pass on the ride home. Most spotted gets bragging rights."],"vibes":["creative","social","weird"],"location":{"name":"Northrup King Building","area":"Northeast","lat":45.00375,"lng":-93.2502},"durationMin":120,"costPerPerson":10,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":2,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_eat_street_roulette',false,'{"id":"q_eat_street_roulette","title":"Eat Street Roulette","hook":"You don''t order for yourself. The person on your left does.","mission":"Nicollet Avenue''s Eat Street has pho, banh mi, tacos and pan dulce within a few blocks. Hit three places none of you have been to, and at every stop someone else orders your food.","steps":["Take the 2 bus west on Franklin Ave to Nicollet (about 25 minutes from the West Bank) and walk south, or bike about 20 minutes. Eat Street runs from around Franklin down to 29th St.","Pick three spots nobody in the group has tried, like Pho 79 or Quang for pho, Lu''s Sandwiches for banh mi, Marissa''s Bakery for conchas, or the Eat Street Crossing food hall.","At each stop, the person on your left orders for you. $10 cap per stop, allergies respected, no vetoes. A bowl of pho costs more than that, so pho orders get split two ways.","At the end, everyone rates how well their orderer knows them, 1-10."],"vibes":["food","social","weird"],"location":{"name":"Eat Street (Nicollet Ave)","area":"Whittier","lat":44.95637,"lng":-93.27766},"durationMin":120,"costPerPerson":25,"groupMin":2,"groupMax":5,"weirdness":3,"adventure":3,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_isles_loop_confession',false,'{"id":"q_isles_loop_confession","title":"Lake of the Isles Skate Loop","hook":"Free rinks on a frozen lake, lights on, skyline behind you, hot chocolate after.","mission":"Once winter locks in, the Park Board lights up free skating rinks on Lake of the Isles. Go after dark, skate a loop as a group, and get the skyline shot from the ice.","steps":["Wait for rink season (usually mid-December to mid-February). Rinks are lit daily 4:30-9pm. Take the E Line down Hennepin to Hennepin & 25th St, then walk about 10 minutes west to the rinks at E Lake of the Isles Pkwy and W 26th St.","Bring your own skates or ask at the warming house about loaners.","Skate a loop linked arm in arm. Whoever breaks the chain first buys hot chocolate.","Warm up in the warming house (weekdays 5-9pm, Sat noon-9pm, Sun 1-5pm), then take the skyline photo from the rink.","Skate only on the maintained rink ice, never the open lake."],"vibes":["active","outdoors","social","chill"],"location":{"name":"Lake of the Isles rinks (E Lake of the Isles Pkwy & W 26th St)","area":"East Isles","lat":44.9576,"lng":-93.3043},"durationMin":90,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":3,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_skyway_maze',false,'{"id":"q_skyway_maze","title":"Skyway Speedrun","hook":"Cross downtown without touching a sidewalk. No maps after your first wrong turn.","mission":"Minneapolis has 9.5 miles of skyways, and every building keeps its own hours. Two teams race from the IDS Crystal Court to the U.S. Bank Stadium end of the system using only the signs.","steps":["Green Line to Nicollet Mall. Meet in the IDS Center''s Crystal Court on a weekday before 5pm, when most skyways are open.","Two teams, same start, same finish: the skyway door on the northwest side of U.S. Bank Stadium. It usually only opens on event days, so the first team to touch it (or the last open skyway door before it) wins.","One map look allowed at the start. After your first wrong turn, signs only.","Walk, don''t run: these are office hallways. Step outside and your team goes back to the last skyway door.","Time it. Walk out to U.S. Bank Stadium station for the Green Line home. Losers buy hot chocolate on the way."],"vibes":["active","competitive","weird"],"location":{"name":"IDS Center Crystal Court","area":"Downtown","lat":44.97612,"lng":-93.27202},"durationMin":60,"costPerPerson":4,"groupMin":2,"groupMax":8,"weirdness":3,"adventure":3,"bestTime":["morning","afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_spoon_cherry_standoff',false,'{"id":"q_spoon_cherry_standoff","title":"Spoonbridge Standoff","hook":"Pose as a sculpture, your friends guess which one, then everyone becomes the cherry.","mission":"The Sculpture Garden is free and open until midnight, and on Thursdays the Walker next door is free from 5 to 9pm. Everyone secretly claims a sculpture, acts it out, and the group guesses.","steps":["Go on a Thursday after 5pm. Walk the Walker galleries for free, then head out into the garden.","Everyone secretly picks one sculpture. No telling.","Take turns posing as yours while the group guesses. Fewest correct guesses loses.","Find James Turrell''s Sky Pesher, the sunken room with a hole in the ceiling, and sit there five minutes as the sky changes.","End at Spoonbridge and Cherry for the group recreation. The loser plays the cherry."],"vibes":["weird","creative","social","outdoors"],"location":{"name":"Minneapolis Sculpture Garden","area":"Lowry Hill / Loring Park","lat":44.97028,"lng":-93.28914},"durationMin":90,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":5,"adventure":2,"bestTime":["afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_cedar_riverside_sampler',false,'{"id":"q_cedar_riverside_sampler","title":"Cedar Ave Shaah Summit","hook":"Two Somali spots, two rounds of spiced tea, and everyone orders one thing they''ve never heard of.","mission":"Cedar-Riverside is the center of Minneapolis''s Somali community and a 10-minute walk from West Bank classes. Compare shaah (spiced milk tea) and sambusas at two neighborhood spots, and let everyone take one menu gamble.","steps":["Start at New Cedar (510 Cedar Ave S), then walk down Cedar to Soma Grill & Deli. Hours can shift, so call or check before you go.","At each stop, order a round of shaah for the table and one sambusa each.","Across the two stops, everyone orders one dish they can''t describe. Stuck? Ask what they''d recommend.","Score the tea and sambusas at both places. Group picks a winner.","These are neighborhood spots, not a photo op. Tip well and don''t film people."],"vibes":["food","social","chill"],"location":{"name":"New Cedar (Cedar Ave)","area":"Cedar-Riverside","lat":44.9683,"lng":-93.24746},"durationMin":75,"costPerPerson":12,"groupMin":2,"groupMax":5,"weirdness":2,"adventure":2,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_boom_island_sunset',false,'{"id":"q_boom_island_sunset","title":"Boom Island Sunset Bet","hook":"Bet on the exact minute the sun disappears, watch downtown go gold, then walk the island to the glowing Grain Belt sign.","mission":"Boom Island Park looks straight across the river at the downtown skyline, and hardly anyone from campus goes. At sunset the towers go gold, then pink, then light up. Settle a sunset bet at the point, then walk across Nicollet Island to the Grain Belt sign by the Hennepin Avenue Bridge.","steps":["Bike about 15 minutes from Dinkytown to Boom Island Park. Get to the river''s edge facing downtown 20 minutes before sunset with snacks and a blanket.","No phones: everyone writes down the exact minute they think the sun will disappear behind the buildings across the river.","Watch the skyline go gold, then pink, then lit. Closest guess wins.","Walk south across Nicollet Island to the Hennepin Avenue Bridge (about 15-20 minutes) and take a group shot with the lit Grain Belt sign behind you.","The winner picks the route home and the food stop."],"vibes":["chill","outdoors","social","competitive"],"location":{"name":"Boom Island Park","area":"Northeast / Nicollet Island","lat":44.99228,"lng":-93.2686},"durationMin":75,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":2,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_east_bank_late_library',false,'{"id":"q_east_bank_late_library","title":"Weird Book Hunt in the Stacks","hook":"Twenty minutes in the library stacks to find the strangest real book the U owns.","mission":"Wilson Library''s stacks go on forever and almost nobody browses them anymore. Everyone takes a floor, hunts for the most unexplainable real title, and pitches it outside like a book report.","steps":["Meet at Wilson Library (309 19th Ave S) Monday to Thursday, any time before 10pm (Fridays it closes at 6). Bring your U Card; you need it to get in. The plaza is under construction, so come in from the north side by Social Sciences.","Everyone takes a different floor. 20 minutes to find the strangest legit title. Bonus for anything before 1950 or with a diagram nobody asked for.","Photograph the cover and title page, then leave the book on a reshelving cart. Library voices.","Regroup outside. 30-second pitch each, then vote. Winner picks dinner."],"vibes":["weird","chill","creative","competitive"],"location":{"name":"Wilson Library","area":"West Bank (campus)","lat":44.97082,"lng":-93.24359},"durationMin":45,"costPerPerson":0,"groupMin":2,"groupMax":5,"weirdness":4,"adventure":1,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_uptown_thrift_outfit',false,'{"id":"q_uptown_thrift_outfit","title":"$15 Thrift Fit-Off on Lyndale","hook":"Draw a name, build their whole outfit for $15, and they wear it to dinner.","mission":"Old School by Steeple People is a nonprofit thrift store on Lyndale near Uptown with actually cheap racks. You style someone else, and they wear the result to dinner in Lyn-Lake.","steps":["Open Wed-Sun, 11am-6pm, at 2728 Lyndale Ave S. Bike the Midtown Greenway (about 25 min) or take the E Line down Hennepin and walk about 12 minutes east.","Draw names. You get $15 and 45 minutes to build that person''s full outfit.","No mirror checks for the person being dressed until the reveal.","Everyone changes and walks to dinner in Lyn-Lake wearing the fit. Group votes best look. Worst styling buys fries."],"vibes":["creative","social","weird","competitive"],"location":{"name":"Old School by Steeple People","area":"Lyn-Lake / Uptown","lat":44.95289,"lng":-93.28832},"durationMin":120,"costPerPerson":15,"groupMin":2,"groupMax":5,"weirdness":4,"adventure":3,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_mill_city_ruins_echo',false,'{"id":"q_mill_city_ruins_echo","title":"Mill Ruins + the Flour Tower","hook":"Ride a freight elevator through a flour mill that exploded in 1878, then look down on the falls from the ninth floor.","mission":"Mill City Museum is built inside the ruins of the Washburn A Mill, which blew up in 1878 and burned again in 1991. The Flour Tower elevator show and the observation deck are the good parts, and the ruins park outside is free.","steps":["Walk over the Stone Arch Bridge to Mill City Museum (704 S 2nd St). College students get in for $12, tickets on-site only. Check the day''s hours first.","Before the Flour Tower, everyone guesses how many pounds of flour this mill could grind in a day. Closest guess skips the snack bill. (The answer is in the museum.)","Ride the Flour Tower show, then go up to the observation deck for St. Anthony Falls and the Stone Arch.","Walk down into Mill Ruins Park along the river and trace where the old water channels ran under the mills."],"vibes":["chill","weird","social"],"location":{"name":"Mill City Museum / Mill Ruins Park","area":"Mill District","lat":44.9788,"lng":-93.25723},"durationMin":120,"costPerPerson":12,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":2,"bestTime":["morning","afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_bde_maka_ska_polar',false,'{"id":"q_bde_maka_ska_polar","title":"Last Dip Before Winter","hook":"Knees in the lake before it freezes. Longest holdout renames the group chat.","mission":"A daylight cold-water dare at Bde Maka Ska''s North Beach while the lake is still liquid. Nobody goes past their knees, nobody goes alone, nobody stays past five minutes, and there''s hot chocolate waiting on shore.","steps":["Pick a calm, sunny October afternoon. Bike the Midtown Greenway west to the lake, or take the E Line to Uptown Transit Station and walk about 15 minutes west on Lake St.","North Beach only. Skip it if the beach is posted closed for water quality, or if it''s windy or wavy. Lifeguards are done for the season, so your group is the lifeguard.","Shoes off, everyone wades to knee depth together. Nobody goes deeper and nobody goes in alone. Hard cap of 5 minutes, and anyone whose feet go numb gets out.","Towels, dry socks and a thermos on shore. Longest holdout, or the first to hit the 5-minute cap, renames the group chat."],"vibes":["active","outdoors","competitive","weird"],"location":{"name":"Bde Maka Ska North Beach","area":"Bde Maka Ska / Uptown","lat":44.94905,"lng":-93.31413},"durationMin":60,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":4,"adventure":4,"bestTime":["afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_farmers_market_dare',false,'{"id":"q_farmers_market_dare","title":"The Vegetable You Can''t Name","hook":"Buy the thing nobody can identify, ask the farmer how to cook it, then do exactly that.","mission":"Saturday morning at Mill City Farmers Market, right by the Stone Arch Bridge. Everyone buys produce nobody in the group can name, gets cooking instructions straight from the grower, and you cook it all together that night.","steps":["Walk over the Stone Arch Bridge to the market (704 S 2nd St), Saturdays 9am-1pm in October. From November it moves inside Mill City Museum on the 1st and 3rd Saturdays.","Everyone gets $8 and must buy one item nobody in the group can name. If someone names it, it doesn''t count.","Ask the grower one question: how would you cook this? Write the answer down word for word.","Cook everything that night exactly as told, then rank the dishes."],"vibes":["food","creative","social"],"location":{"name":"Mill City Farmers Market","area":"Mill District","lat":44.9788,"lng":-93.25723},"durationMin":120,"costPerPerson":8,"groupMin":2,"groupMax":5,"weirdness":3,"adventure":3,"bestTime":["morning"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_late_diner_menu_dare',false,'{"id":"q_late_diner_menu_dare","title":"Fourth From the Bottom at Hard Times","hook":"Everyone orders the fourth item up from the bottom of the board. No swaps.","mission":"Hard Times Cafe on the West Bank is a worker-run vegetarian cafe with breakfast all day and doors open until midnight. Let the menu board pick your order and see who got lucky.","steps":["Walk across the Washington Ave Bridge to Hard Times (1821 Riverside Ave) by 11pm. It closes at midnight. Bring cash just in case.","Everyone takes a different section of the board and counts four up from the bottom. That''s your order. Allergies get a one-item bump, nothing else does.","Add a cheap coffee for the table and pass bites around.","Rate the luck of your draw out of 10. Lowest score picks the next quest."],"vibes":["food","late-night","social","weird"],"location":{"name":"Hard Times Cafe","area":"Cedar-Riverside / West Bank","lat":44.96959,"lng":-93.24617},"durationMin":60,"costPerPerson":10,"groupMin":2,"groupMax":5,"weirdness":3,"adventure":2,"bestTime":["evening","late"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_surdyks_cheese_gamble',false,'{"id":"q_surdyks_cheese_gamble","title":"The $6 Cheese Gamble","hook":"Buy the cheese you can''t pronounce, picnic on Nicollet Island, then put one old house on trial for being haunted.","mission":"Surdyk''s Cheese Shop on East Hennepin is a 5-minute walk from Nicollet Island''s row of restored Victorian houses. Blind-rank the cheeses on the grass, then walk the island and argue about which house is haunted.","steps":["Surdyk''s Cheese Shop, 303 E Hennepin Ave (9am-8pm Mon-Sat, 11am-6pm Sun). $6 each: buy the cheese whose name you can least pronounce. One person grabs bread.","Walk to the lawn near the Nicollet Island Pavilion. Taste blind. Nobody reveals their pick until the ranking is done.","Walk the island''s residential streets. Everyone nominates the house they think is haunted. Stay on the sidewalk; people live there.","Closing arguments on the walk back over the Hennepin Avenue Bridge. Majority verdict wins."],"vibes":["food","chill","weird","social"],"location":{"name":"Nicollet Island","area":"Nicollet Island / East Hennepin","lat":44.9871,"lng":-93.2626},"durationMin":90,"costPerPerson":8,"groupMin":2,"groupMax":5,"weirdness":3,"adventure":2,"bestTime":["afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_light_rail_dice',false,'{"id":"q_light_rail_dice","title":"Green Line Roulette","hook":"Roll two dice, ride that many stops, and find the best $8 bite within three blocks.","mission":"Board the Green Line at East Bank and let the dice decide where you get off along University Avenue, one of the best cheap-food corridors in the Twin Cities. A high roll lands you in Little Mekong.","steps":["Board eastbound at East Bank station. Tap your U Card: the Universal Transit Pass makes the ride free (otherwise it''s $2, good for 2.5 hours).","Roll two dice and add them. That''s how many stops you ride east.","Get off. Everyone has $8 and 20 minutes to find the best thing to eat within three blocks. Nothing to eat nearby? Roll one die and ride on.","Regroup, taste everything, vote. The loser rolls for the next ride."],"vibes":["food","weird","social"],"location":{"name":"East Bank Station (Green Line)","area":"East Bank (campus)","lat":44.97368,"lng":-93.23108},"durationMin":120,"costPerPerson":8,"groupMin":2,"groupMax":6,"weirdness":4,"adventure":4,"bestTime":["afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_pinball_tournament',false,'{"id":"q_pinball_tournament","title":"Can Can Pinball Bracket","hook":"Artist-built mini golf, then a pinball bracket where whoever''s knocked out does live commentary.","mission":"Can Can Wonderland in St. Paul fills an old can factory with weird artist-designed mini golf holes and a big pinball arcade. Play the course, then run a single-elimination bracket.","steps":["Green Line to Fairview Ave, then about a 12-minute walk north to 755 Prior Ave N. It''s family-friendly; go in the afternoon or early evening, since some late weekend hours are 21+.","Play the mini golf course first. Lowest score gets the top seed.","Pinball bracket, one game per round. Whoever gets knocked out has to commentate the next match out loud.","Champion picks the group''s next quest. Last place buys floats at the soda fountain."],"vibes":["competitive","social","weird"],"location":{"name":"Can Can Wonderland","area":"Midway, St. Paul","lat":44.96512,"lng":-93.18318},"durationMin":150,"costPerPerson":20,"groupMin":3,"groupMax":6,"weirdness":3,"adventure":2,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_greenway_night_ride',false,'{"id":"q_greenway_night_ride","title":"Greenway to the Lake Time Trial","hook":"Ride the Greenway from the Sabo Bridge to Bde Maka Ska, time it, then cruise back slow.","mission":"The Midtown Greenway is a bike highway sunk below street level across south Minneapolis. Time the ride to the lake, catch the sunset there, and take the scenic version home.","steps":["Bring your own bike or grab a Lime. Meet at the Sabo Bridge over Hiawatha Ave about an hour before sunset (around 6pm in late September).","Ride west on the Greenway to Bde Maka Ska, about 3.5 miles. One person runs the stopwatch and the clock never pauses, but everyone makes a full stop at the three street crossings near the lake (James, Irving and Humboldt) and slows down around walkers.","Watch the sunset from the lake''s north shore by North Beach.","Ride back slower. Everyone gets to call one stop on the way: a mural, a snack, a bench. Lights on after dark."],"vibes":["active","outdoors","social"],"location":{"name":"Martin Olav Sabo Bridge (Midtown Greenway)","area":"Seward / Longfellow","lat":44.95423,"lng":-93.24263},"durationMin":120,"costPerPerson":0,"groupMin":2,"groupMax":5,"weirdness":1,"adventure":3,"bestTime":["afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_arboretum_of_alleys',false,'{"id":"q_arboretum_of_alleys","title":"Witch''s Hat Color Hunt","hook":"Climb the highest hill near campus, nominate the reddest tree in sight, and watch downtown go gold.","mission":"Tower Hill Park in Prospect Park sits on one of the highest points in Minneapolis, under the 1914 Witch''s Hat water tower, about a 25-minute walk from the middle of campus. At peak color the whole neighborhood below goes red and orange.","steps":["Walk about 25 minutes east from East Bank, or take the Green Line to Prospect Park (or the E Line to University & Malcolm) and walk about 8 minutes uphill to 55 Malcolm Ave SE.","Bring cider and donuts. Get there 30 minutes before sunset.","Everyone nominates the reddest tree they can see from the top and makes a 30-second case. Vote.","Watch the sun drop behind downtown. Stay on the grass: the tower itself is closed except one day a year."],"vibes":["outdoors","chill","social"],"location":{"name":"Tower Hill Park (Witch''s Hat)","area":"Prospect Park","lat":44.96883,"lng":-93.21268},"durationMin":60,"costPerPerson":5,"groupMin":1,"groupMax":6,"weirdness":2,"adventure":1,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_002',false,'{"id":"q_002","title":"Flats Skip-Off","hook":"Take the stairs down to the river under campus and settle who can actually skip a rock.","mission":"East River Flats is a riverside park right below the East Bank that a lot of students never find. Go at golden hour and run a stone-skipping tournament on the shore.","steps":["Take the stairs next to the Weisman down to East River Flats. If riverfront restoration has part of the shore fenced off, use whatever stretch is open.","Walk the shoreline toward the Washington Ave Bridge. Everyone collects five flat stones.","Best of three throws each, called out loud and confirmed by the group. Only throw when no rowers or boats are on the water in front of you, since the Gophers'' rowing boathouse is right here.","Stay on the shore; the current is strong, so no wading.","Loser carries snacks on the next quest. Go back up a different set of stairs."],"vibes":["outdoors","competitive","chill"],"location":{"name":"East River Flats Park","area":"East Bank (campus)","lat":44.97118,"lng":-93.2366},"durationMin":45,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":2,"bestTime":["afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_008',false,'{"id":"q_008","title":"Race the Campus Connector","hook":"Bike to the St. Paul campus. If the bus beats you, you buy the coffee.","mission":"The Campus Connector (route 121) runs between the Minneapolis and St. Paul campuses about every 7 minutes on weekdays. Take the bike trail along the Transitway and try to beat the next bus.","steps":["Meet at the Transitway & 23rd Ave SE bus stop in Stadium Village with bikes, your own or Lime. Go on a weekday between 7am and 6pm, when buses come every 7 minutes.","Wait for an eastbound Campus Connector to pull away from the stop, then go.","Ride the bike trail beside the Transitway. Never ride on the bus-only road itself, and stop at every street crossing, even mid-race.","If the bus reaches the St. Paul Student Center stop before you, you buy coffee. Winners pick where."],"vibes":["active","competitive","outdoors"],"location":{"name":"Transitway & 23rd Ave SE stop (Stadium Village)","area":"Stadium Village","lat":44.9755,"lng":-93.22263},"durationMin":45,"costPerPerson":5,"groupMin":2,"groupMax":5,"weirdness":2,"adventure":3,"bestTime":["morning","afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_010',false,'{"id":"q_010","title":"Find Hidden Falls","hook":"Bike the river road through peak color to a waterfall that''s smaller than its name.","mission":"The river road from campus into St. Paul is one of the best fall bike rides in the Twin Cities, and at the end is Hidden Falls Regional Park. Walk the creek trail until you find the actual falls.","steps":["Check St. Paul Parks closure notices first; the north entrance road is due for resurfacing.","Bike south from campus on East River Parkway. It becomes Mississippi River Blvd at the St. Paul line, no bridge needed. Ride to Magoffin Ave, about 5.5 miles (35-40 min) each way.","Enter at the north entrance near Magoffin Ave, walk past the picnic shelters toward the river, then follow the trail northwest along the creek. Shortcut: a paved path from Ungci Makha Park leads to a new overlook above the falls.","Everyone guesses the falls'' height before you see them. Closest guess gets the first snack. Wear shoes that can get muddy."],"vibes":["outdoors","active","chill"],"location":{"name":"Hidden Falls (Hidden Falls Regional Park)","area":"Highland Park, St. Paul","lat":44.91,"lng":-93.1922},"durationMin":180,"costPerPerson":0,"groupMin":2,"groupMax":5,"weirdness":1,"adventure":3,"bestTime":["afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_011',false,'{"id":"q_011","title":"Gorge Walk, Two Cities","hook":"Hike the dirt trail down in the river gorge, then stand in Minneapolis and St. Paul at once.","mission":"The Winchell Trail runs below street level through the Mississippi gorge, and the Park Service says peak color here usually hits between the end of September and the first weekend of October. Walk it to the Lake Street Bridge, stand on the city line, and loop back on the other side.","steps":["Start at the west end of the Franklin Ave Bridge and take the path down to the Winchell Trail.","Walk south under the maples. Everyone hunts for the single reddest tree; vote when you reach the Lake Street-Marshall Bridge.","Walk to the middle of the bridge. The city line runs down the center of the river, so that''s your spot for the one-foot-in-each-city photo.","Loop back north on the St. Paul side along Mississippi River Blvd and East River Pkwy, then recross on the Franklin Ave Bridge."],"vibes":["outdoors","active","chill"],"location":{"name":"Winchell Trail (Franklin Ave Bridge)","area":"Seward / Longfellow","lat":44.96367,"lng":-93.22302},"durationMin":150,"costPerPerson":0,"groupMin":1,"groupMax":6,"weirdness":1,"adventure":3,"bestTime":["morning","afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_012',false,'{"id":"q_012","title":"Ten Laps at Van Cleve","hook":"Free rink, 10 minutes from Dinkytown, borrowed skates only.","mission":"Van Cleve Park''s outdoor rink is the easiest way to try skating if you''ve never done it. Skate ten laps under the lights and thaw out in the warming house between sets.","steps":["Wait for rink season (usually late December to mid-February). The rink is lit from 4:30pm.","Borrow skates from someone in your building. Don''t buy any yet.","Skate ten laps as a group. Anyone who falls picks the next lap''s rule: backwards, holding hands, no arms.","Warm up in the warming house (weekdays 5-9pm) between sets."],"vibes":["active","outdoors","social"],"location":{"name":"Van Cleve Park","area":"Southeast Como","lat":44.98686,"lng":-93.23188},"durationMin":60,"costPerPerson":0,"groupMin":1,"groupMax":6,"weirdness":1,"adventure":2,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_016',false,'{"id":"q_016","title":"Summit Avenue Mansion Draft","hook":"Walk the grandest street in the Twin Cities and draft the mansion you''d live in.","mission":"Summit Avenue in St. Paul is the longest stretch of Victorian homes in the country, under big old trees that go gold in October. Walk it from the James J. Hill House and draft houses like a fantasy league. Skip Sunday Oct 4, when the marathon takes over the street.","steps":["Green Line to Capitol/Rice St and walk about 15 minutes to the Cathedral of St. Paul. Summit starts at the James J. Hill House next door.","Walk west. Snake draft: each person claims one house per block. One trade allowed.","At Dale or Lexington, everyone defends their mansion. Group votes on who drafted best.","Drop one block south to Grand Ave for food. To get home, walk about 20 minutes north up Lexington to the Green Line, or catch the B Line on Selby toward downtown St. Paul."],"vibes":["outdoors","chill","social","competitive"],"location":{"name":"Summit Avenue (James J. Hill House)","area":"Cathedral Hill, St. Paul","lat":44.9451,"lng":-93.10893},"durationMin":150,"costPerPerson":0,"groupMin":2,"groupMax":5,"weirdness":2,"adventure":2,"bestTime":["afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_020',false,'{"id":"q_020","title":"Tropics in a Blizzard","hook":"On the coldest day of the year, walk into a free palm house and strip down to your vacation shirt.","mission":"Como''s Marjorie McNeely Conservatory is a free Victorian glass house kept tropical all winter. Wear vacation clothes under your parka, shed it in the Palm Dome, and shoot the fake beach trip.","steps":["Wait for a subzero day. Take the 3 bus along Como Ave (about 35-40 minutes). Open daily 10am-4pm, free.","Wear your most vacation outfit under your coat: sunglasses, Hawaiian shirt, sandals in a bag.","In the Palm Dome, coats off. Most convincing ''we''re in Bali'' photo wins.","Walk the Sunken Garden flower show on the way out (the holiday show runs in December)."],"vibes":["weird","chill","creative"],"location":{"name":"Marjorie McNeely Conservatory","area":"Como Park, St. Paul","lat":44.98191,"lng":-93.15143},"durationMin":90,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":4,"adventure":1,"bestTime":["morning","afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_021',false,'{"id":"q_021","title":"Endless Bridge + the Amber Box","hook":"Walk into the Guthrie without a ticket and stand 178 feet out over the riverfront.","mission":"The Guthrie''s cantilevered Endless Bridge and the yellow-glass Amber Box on Level 9 are free and open to the public, and most students don''t know you can just walk in. Go at golden hour, then catch the last light from Gold Medal Park.","steps":["Walk over from campus via the Stone Arch Bridge (about 30 min) or take the Green Line to Downtown East. Public lobbies are closed Mondays, so check the day''s hours.","Take the escalator up and walk to the very end of the Endless Bridge. Sunset photo over the river.","Take the elevator to Level 9 and look at the city through the amber glass. Group photo, everyone yellow.","Walk the spiral path to the top of Gold Medal Park next door for the last of the light."],"vibes":["chill","creative","outdoors"],"location":{"name":"Guthrie Theater","area":"Mill District / Downtown East","lat":44.97823,"lng":-93.25552},"durationMin":60,"costPerPerson":0,"groupMin":1,"groupMax":6,"weirdness":1,"adventure":1,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_040',false,'{"id":"q_040","title":"The Frozen Falls","hook":"After a real cold snap, Minnehaha Falls freezes into a wall of blue ice, one train ride away.","mission":"In a deep January or February freeze, the 53-foot falls turn into an ice column. Photograph it from the overlook and the marked viewing areas, then get back on the train before your fingers quit.","steps":["Wait for a week of below-zero nights. Blue Line to 50th St/Minnehaha Park.","Photograph the ice from the upper overlook first, then from the marked lower viewing areas.","Stay on marked paths. Never walk onto the ice or behind the falls.","Best shot gets hot chocolate bought for them on the way home."],"vibes":["outdoors","chill","creative"],"location":{"name":"Minnehaha Falls","area":"Minnehaha / Longfellow","lat":44.91555,"lng":-93.21125},"durationMin":60,"costPerPerson":0,"groupMin":1,"groupMax":6,"weirdness":1,"adventure":2,"bestTime":["morning","afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_044',false,'{"id":"q_044","title":"Como Day for $4","hook":"Free zoo, four polar bears, a witch-themed flower show, and a century-old carousel.","mission":"Como Park Zoo & Conservatory is free, and right now the Sunken Garden fall show is built around witches'' gardens (through Oct 18). Add the old carousel on a weekend and you''ve got a whole afternoon for about $4.","steps":["Green Line to Lexington Pkwy station, then the 83 bus north into Como Park (about 45 minutes total), or bike about 25 minutes. Zoo and conservatory are free, 10am-4pm daily.","Polar bears first. Como has four. Best photo of a bear actually doing something wins.","Walk the Sunken Garden: deep purple and dark red mums with witches''-garden plants until Oct 18, then a yellow-and-red mum show Oct 23 to Nov 29.","Weekends through Nov 1, 11am-4pm: ride Cafesjian''s Carousel ($4). Everyone picks the animal with the strangest face. It doesn''t run below 45 degrees."],"vibes":["chill","outdoors","weird"],"location":{"name":"Como Park Zoo & Conservatory","area":"Como Park, St. Paul","lat":44.98253,"lng":-93.15393},"durationMin":150,"costPerPerson":4,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":1,"bestTime":["morning","afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_047',false,'{"id":"q_047","title":"First Footprints on Northrop Mall","hook":"The morning after the first real snow, beat everyone to Northrop Mall and make the first tracks.","mission":"After an overnight snowfall, the big lawns on either side of Northrop Mall stay perfectly blank until the 8am crowd starts cutting across. Crews plow the paths, not the grass, so the lawns are your canvas. Get there first.","steps":["Group-chat rule: if 2+ inches fall overnight, everyone meets on the Northrop steps at 7am.","Photograph the untouched lawns from the steps looking toward Coffman.","Then make the first footprints count: stamp out a giant message on the lawn or lay down a row of snow angels.","Hot drinks after, before your first class."],"vibes":["outdoors","creative","social"],"location":{"name":"Northrop Mall","area":"East Bank (campus)","lat":44.97484,"lng":-93.23536},"durationMin":45,"costPerPerson":3,"groupMin":2,"groupMax":8,"weirdness":3,"adventure":2,"bestTime":["morning"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_049',false,'{"id":"q_049","title":"14 Stools at Al''s","hook":"The narrowest restaurant in Minneapolis has 14 stools. You wait standing behind them until one opens.","mission":"Al''s Breakfast has been squeezed into a 10-foot-wide former Dinkytown alley since 1950. Go as a small group, wait along the back wall, and eat pancakes at the counter next to regulars.","steps":["Go on a weekday morning before class. Open Mon-Sat 6am-1pm, Sun 9am-1pm. Weekends and game days mean a long line.","Groups of 2-4 only. You''ll get split up as stools open, which is part of it.","Rule: whoever sits first orders a stack of blueberry pancakes for the whole group to share.","Eat and go; someone''s waiting behind you. Bring cash just in case."],"vibes":["food","social","chill"],"location":{"name":"Al''s Breakfast","area":"Dinkytown","lat":44.98104,"lng":-93.23557},"durationMin":60,"costPerPerson":12,"groupMin":2,"groupMax":4,"weirdness":2,"adventure":2,"bestTime":["morning"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_054',false,'{"id":"q_054","title":"Co-op Chopped","hook":"$6 each, one mystery ingredient for a partner, and dinner has to use all of it.","mission":"Seward Co-op on Franklin is a big neighborhood grocery a short bike ride from West Bank. Everyone buys one weird ingredient for someone else, then you cook one shared dinner that uses every single one.","steps":["Meet at Seward Co-op (2823 E Franklin Ave, open 8am-10pm). The 2 bus stops right there.","Draw names. You get $6 to buy one ingredient your person has to cook with. Bulk bins count.","Pool another $6 for staples like rice, pasta and onions.","Cook together that night. Every mystery ingredient has to show up somewhere. Best dish skips dish duty."],"vibes":["food","creative","social","competitive"],"location":{"name":"Seward Community Co-op (Franklin)","area":"Seward","lat":44.9624,"lng":-93.23027},"durationMin":150,"costPerPerson":8,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":2,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_057',false,'{"id":"q_057","title":"Grand Ave, Dessert First","hook":"Dessert, then dinner, then coffee to walk with. Reverse order, no chains.","mission":"Grand Avenue is St. Paul''s walkable main street. Start at Grand Ole Creamery, find dinner within eight blocks, and finish with a coffee for the walk.","steps":["Green Line to Victoria St, then walk about 25 minutes south (or bike) to Grand Ole Creamery, 750 Grand Ave. Open noon-10pm Mon-Sat, 11am-9pm Sun.","Everyone gets a different flavor in a fresh waffle cone and passes cones around.","Dinner has to be within eight blocks and not a chain. Three minutes to decide.","End with a coffee to walk with, like Cafe Latte at 850 Grand (open till 10pm)."],"vibes":["food","social","chill"],"location":{"name":"Grand Ole Creamery","area":"Grand Ave, St. Paul","lat":44.93983,"lng":-93.13188},"durationMin":120,"costPerPerson":25,"groupMin":2,"groupMax":5,"weirdness":2,"adventure":2,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_061',false,'{"id":"q_061","title":"Ice Cream the U Made","hook":"The U makes its own ice cream and sells it three hours a week. The tiny window is the point.","mission":"The Meat & Dairy Salesroom in the Andrew Boss Lab on the St. Paul campus sells ice cream made in the U''s own food science pilot plant, in about 40 flavors. It''s only open Wednesday afternoons, so ride the Campus Connector over and blind-rank pints.","steps":["Wednesdays 2-5pm only. Take the Campus Connector (121) to St Paul Student Center and walk about 5 minutes to 1354 Eckles Ave.","Find the salesroom in Room 166 of the Andrew Boss Lab of Meat Science. The ice cream comes in pints ($6), not scoops, so everyone buys a different flavor. Bring spoons.","Sit outside, pass the pints around blind, and rank them.","Missed the window? Goldy''s Gameroom in Coffman scoops campus-made ice cream for $2.59 (closed Sundays)."],"vibes":["food","weird","chill"],"location":{"name":"Meat & Dairy Salesroom (Andrew Boss Lab)","area":"St. Paul campus","lat":44.98171,"lng":-93.18479},"durationMin":60,"costPerPerson":6,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":2,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_062',false,'{"id":"q_062","title":"Juicy Lucy Civil War","hook":"Two Cedar Ave spots both say they invented the cheese-stuffed burger. Your group settles it.","mission":"Matt''s Bar spells it Jucy Lucy, the 5-8 Club spells it Juicy Lucy, and both claim they were first. Split one at each, score them, and pick a side.","steps":["Start at Matt''s Bar (3500 Cedar Ave S). Cash only, ATM inside. Kids and families are welcome, so under-21s are fine.","Split one Jucy Lucy per pair. Wait two full minutes before biting; the cheese is molten. Anyone who ignores this cleans the table.","Bus or bike about 3 miles south on Cedar to the 5-8 Club (5800 Cedar Ave S), a family restaurant that takes cards, and split their Juicy Lucy.","Score cheese pull, burn factor, bun and fries. Secret vote. The losing side buys dessert."],"vibes":["food","competitive","social"],"location":{"name":"Matt''s Bar","area":"Powderhorn","lat":44.93943,"lng":-93.24764},"durationMin":150,"costPerPerson":22,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":3,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_063',false,'{"id":"q_063","title":"Sambusa Showdown","hook":"Campus sambusa vs. Lake Street sambusa. Scored, argued over, settled.","mission":"Afro Deli in Stadium Village is where a lot of students try Somali food for the first time. Score its sambusas, then head to Midtown Global Market and see if 7 Spices'' golden chicken sambusa can beat it.","steps":["Round 1 at Afro Deli (720 Washington Ave SE, daily 10:30am-7pm): split a beef, a chicken and a veggie sambusa plus one Somali spiced tea. Score crunch, filling and sauce out of 10.","Get to Midtown Global Market (920 E Lake St): bike about 25 minutes (the Midtown Greenway is the easy way), or take the Green Line to U.S. Bank Stadium, switch to the Blue Line to Lake St/Midtown, and catch a westbound Lake Street bus to Chicago Ave.","Round 2 at 7 Spices inside the market (open until 8pm, 6pm Sundays): order the golden chicken sambusa and score it head-to-head with Afro Deli''s chicken, same three categories.","Add up the totals and crown a champion. Whoever backed the loser buys the next round of tea."],"vibes":["food","competitive","social"],"location":{"name":"Afro Deli (Stadium Village)","area":"Stadium Village","lat":44.97353,"lng":-93.22779},"durationMin":150,"costPerPerson":12,"groupMin":2,"groupMax":5,"weirdness":2,"adventure":2,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_064',false,'{"id":"q_064","title":"Hmongtown Papaya Salad Ladder","hook":"Everyone orders papaya salad at a different spice level. Find the group''s ceiling.","mission":"Hmongtown Marketplace in St. Paul has more than 125 stalls and 11 restaurants, with papaya salad pounded to order in giant mortars. Split everything family-style, with sticky rice and sausage as backup.","steps":["Green Line to Capitol/Rice St, then about a 10-minute walk north to 217 Como Ave. It''s been on temporary hours since January, so call 651-487-3700 first.","Each person orders papaya salad at a different spice level, mild on up. Add Hmong sausage and purple sticky rice for the table.","Everyone tries every level. The hottest one you can finish is your number.","Cool down with a nab vam coconut drink or lychee boba, then wander the stalls. Bring cash, and ask before filming anyone."],"vibes":["food","competitive","social"],"location":{"name":"Hmongtown Marketplace","area":"North End, St. Paul","lat":44.96137,"lng":-93.10905},"durationMin":90,"costPerPerson":12,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":3,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_068',false,'{"id":"q_068","title":"Pick Your Planet at the Bell","hook":"Free with your U Card, $5 for the dome, and everyone has to defend the planet they''d live on.","mission":"The Bell Museum on the St. Paul campus is free for UMN students, and planetarium shows are $5. Walk the famous wildlife dioramas, then lie back under the dome.","steps":["Campus Connector to the St. Paul campus. Open Wed-Sun 10am-4pm, with shows at 10:30, 11:30, 12:30, 1:30 and 2:30.","Before the show, everyone picks the planet they''d live on and makes a 20-second case.","Catch a live show like Minnesota Night Skies. Anyone who changes their planet afterward buys snacks.","Walk the dioramas. Everyone finds the animal that is most them, and the group decides if they''re right.","Free bonus: the October Star Party is Friday, Oct 16, 7-8:30pm."],"vibes":["chill","weird","creative"],"location":{"name":"Bell Museum","area":"St. Paul campus / Falcon Heights","lat":44.9912,"lng":-93.18811},"durationMin":120,"costPerPerson":5,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":1,"bestTime":["morning","afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_069',false,'{"id":"q_069","title":"Lose a Staring Contest to an Owl","hook":"Free with your U Card. You will lose.","mission":"The Raptor Center on the St. Paul campus treats injured eagles, hawks and owls, and its tours are free for UMN students. You get close to birds that never blink first.","steps":["Reserve a tour online or by phone (612-624-4745). Tours run Tue-Sun, the last one at 3pm, max 15 per group.","Campus Connector to the St. Paul campus, then walk over to the Raptor Center.","On the 45-minute tour, everyone picks an owl and holds eye contact. Time it.","On the bus back, whoever remembers the most bird names picks the next quest."],"vibes":["weird","chill","outdoors"],"location":{"name":"The Raptor Center","area":"St. Paul campus","lat":44.98272,"lng":-93.18116},"durationMin":75,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":4,"adventure":1,"bestTime":["afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_071',false,'{"id":"q_071","title":"Mia Thursday Night Race","hook":"Free museum, open late, and 30 minutes to find the oldest, weirdest and most stealable things inside.","mission":"Mia is always free and stays open until 9pm on Thursdays. Split up, race for three finds, pitch them in the lobby, then walk two blocks for cheap pho.","steps":["Go on a Thursday after 6pm. Bike about 25 minutes to 2400 3rd Ave S. Oct 15 is a Third Thursday, Mia''s monthly evening event, so check what''s on.","30 minutes, three categories: the oldest object you can find using wall labels only, the weirdest object, and the one you''d steal.","Phones only for photographing your picks.","Regroup in the lobby. 30-second pitch per find, vote per category. Then walk two blocks to Eat Street for cheap pho."],"vibes":["creative","competitive","weird"],"location":{"name":"Minneapolis Institute of Art (Mia)","area":"Whittier","lat":44.95848,"lng":-93.27415},"durationMin":120,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":2,"bestTime":["evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_072',false,'{"id":"q_072","title":"Gopher Way, No Sky","hook":"Cross the East Bank on the Gopher Way without going outside, and photograph the door where you give up.","mission":"The Gopher Way is the U''s official, signed network of indoor walkways and skyways linking campus buildings. It has gaps, which is the whole game: see how far you get without stepping outside.","steps":["Start in the Moos Tower lobby on a weekday during building hours.","Follow the Gopher Way signs and get as far across the East Bank as you can without going outdoors.","Public, signed walkways only. No staff-only doors, service areas, steam tunnels or anything marked no entry.","Photograph the exact door where you had to give up. Farthest pair picks lunch at Coffman."],"vibes":["weird","active","competitive"],"location":{"name":"Moos Tower (Gopher Way)","area":"East Bank (campus)","lat":44.9729,"lng":-93.23142},"durationMin":45,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":2,"bestTime":["morning","afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_076',false,'{"id":"q_076","title":"Blind Show at the Cedar","hook":"Buy a ticket to a band none of you has heard of. No listening ahead.","mission":"The Cedar Cultural Center is an all-ages nonprofit venue right on the West Bank, a short walk over the Washington Ave Bridge, and students with ID can get $10 door tickets for Cedar-presented shows. Pick an act nobody knows and go in blind.","steps":["Check the Cedar calendar (416 Cedar Ave S) and pick a Cedar-presented show nobody in the group has heard of.","No listening beforehand. You get the one-line description and that''s it.","Bring student ID for $10 door tickets when they''re available. Doors usually open 30-60 minutes before the show.","Stay for the whole set. After, everyone scores it 1-10 and names the one song they''d add to a playlist."],"vibes":["social","weird","late-night"],"location":{"name":"The Cedar Cultural Center","area":"Cedar-Riverside / West Bank","lat":44.96943,"lng":-93.24766},"durationMin":180,"costPerPerson":10,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":3,"bestTime":["evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_079',false,'{"id":"q_079","title":"Retro Bowl Draft","hook":"Wooden lanes from the 1930s, schoolyard-pick teams, and the losing team picks the next quest.","mission":"Bryant-Lake Bowl in Lyn-Lake has been a bowling alley since 1936: classic wooden lanes, bumpers on every lane, and $5 games. Draft teams, bowl one game, and the losers are on the hook.","steps":["Go in the afternoon: games are $5 Sun-Thu and $7 Fri-Sat, shoes $3, and socks are required (they sell them for $2.50). Call 612-825-3737 first, since private events sometimes take the lanes. Kids bowl here too, so under-21s are fine.","Two captains draft teams, one pick at a time.","Bowl one game. Bumpers for anyone who asks, no shame.","Losing team buys fries and picks the group''s next wego quest."],"vibes":["competitive","social"],"location":{"name":"Bryant-Lake Bowl","area":"Lyn-Lake / Uptown","lat":44.9485,"lng":-93.29014},"durationMin":90,"costPerPerson":10,"groupMin":4,"groupMax":8,"weirdness":2,"adventure":1,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_goldys_half_price_bowling',false,'{"id":"q_goldys_half_price_bowling","title":"$2 Bowling Under Coffman","hook":"There''s a bowling alley in Coffman''s basement, and it''s half off three afternoons a week.","mission":"Goldy''s Gameroom charges students $4 a game, and it''s 50% off Monday, Wednesday and Friday until 5pm. Run a bracket between classes.","steps":["Go Mon, Wed or Fri before 5pm: about $2 a game plus $3 shoes.","Seed a bracket with rock-paper-scissors.","One game per round, head to head on neighboring lanes.","Lowest score buys the champ a $2.59 scoop of campus-made ice cream at the counter. Goldy''s also runs weekly bingo and trivia nights if you want round two."],"vibes":["competitive","social"],"location":{"name":"Goldy''s Gameroom (Coffman Union)","area":"East Bank (campus)","lat":44.97282,"lng":-93.23535},"durationMin":90,"costPerPerson":7,"groupMin":2,"groupMax":8,"weirdness":1,"adventure":1,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_tate_telescope_night',false,'{"id":"q_tate_telescope_night","title":"Saturn From Tate Hall","hook":"Every clear Friday during the semester, astronomers open the Tate Hall telescopes to anyone who shows up.","mission":"The Minnesota Institute for Astrophysics runs free public viewing at Tate Hall: a short talk at 8pm, then telescopes on the observing deck and a historic refractor in the dome. It''s a five-minute walk from anywhere on the East Bank.","steps":["Check the MIfA public-observing page for this semester''s Friday dates, then pick a clear night.","Be in Tate Hall room B50 (116 Church St SE) by 8pm for the talk. It runs rain or shine.","Around 8:30, head up to the telescopes if the sky''s clear. Dress warm; you''ll be outside.","Before your turn at the eyepiece, everyone describes what they think they''re about to see. Compare after."],"vibes":["chill","weird","social"],"location":{"name":"Tate Hall","area":"East Bank (campus)","lat":44.97531,"lng":-93.23445},"durationMin":90,"costPerPerson":0,"groupMin":1,"groupMax":6,"weirdness":2,"adventure":2,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_cave_swing_night',false,'{"id":"q_cave_swing_night","title":"Swing Night in a Gangster Cave","hook":"A live big band, a free lesson, and a dance floor inside a sandstone cave.","mission":"Every Thursday the Wabasha Street Caves in St. Paul, home to the Castle Royal nightclub in the 1930s gangster era, host swing night with a beginner lesson and a live big band. Nobody needs to know how to dance.","steps":["Green Line to Central station, then walk about 20 minutes across the Wabasha Street Bridge. Plan on about an hour from campus.","Doors open at 6pm. Be there for the free beginner lesson at 6:15. The band plays 7-10pm.","Bring your student ID: $10 cash or $11 card for students ($15 general). No age limit is listed.","Rule: everyone dances at least three songs, including the people who swear they can''t."],"vibes":["social","active","weird"],"location":{"name":"Wabasha Street Caves","area":"West Side, St. Paul","lat":44.93575,"lng":-93.08702},"durationMin":210,"costPerPerson":10,"groupMin":2,"groupMax":8,"weirdness":3,"adventure":4,"bestTime":["evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_riverview_five_dollar',false,'{"id":"q_riverview_five_dollar","title":"$5 Tuesday at the Riverview","hook":"A restored mid-century movie house, $5 tickets, real-butter popcorn, cash only.","mission":"The Riverview in south Minneapolis charges $5 all day Tuesday and for any show before 6pm. Bring cash, pick the weirdest thing on the calendar, and rate it on the walk out.","steps":["Bike about 20 minutes down West River Parkway to 3800 42nd Ave S, or take the Blue Line to 38th St and walk about 15 minutes.","Everyone brings $10 cash: ticket plus popcorn. There''s an ATM if someone forgets.","Pick the movie by blind vote on the way over. Special screenings and cult classics beat new releases.","Rate it out of 10 on the walk out. Lowest score picks next time."],"vibes":["chill","social"],"location":{"name":"Riverview Theater","area":"Howe / Longfellow","lat":44.93404,"lng":-93.21315},"durationMin":180,"costPerPerson":10,"groupMin":2,"groupMax":8,"weirdness":1,"adventure":1,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_trylon_witch_month',false,'{"id":"q_trylon_witch_month","title":"Witch Month at the Trylon","hook":"Tiny cinema, real film prints, and a whole October of witch movies.","mission":"The Trylon is a small nonprofit cinema in Longfellow, and through October it''s running ''Evil Incantations'', a series on witchcraft, hexes and demons, split between the Trylon and its second screen, Trylon at The Heights. Pick the strangest title and go as a group.","steps":["Check trylon.org for the Evil Incantations lineup (The VVitch, Suspiria in 4K, The Conjuring and Drag Me to Hell on 35mm, Viy, Alucarda and more). Confirm the date and pick a screening at the Trylon itself (2820 E 33rd St), not The Heights in Columbia Heights.","Bike about 20 minutes over the Franklin Ave Bridge, or take the Blue Line to Lake St/Midtown and walk about 15 minutes.","Five of you? Split a Trylon discount card (5 tickets for $30) and it''s $6 each.","After, everyone names the scariest moment. Whoever jumped the most picks the next film."],"vibes":["weird","chill","social"],"location":{"name":"Trylon Cinema","area":"Longfellow","lat":44.94318,"lng":-93.23103},"durationMin":150,"costPerPerson":6,"groupMin":2,"groupMax":5,"weirdness":3,"adventure":2,"bestTime":["evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_techno_contra',false,'{"id":"q_techno_contra","title":"Techno Contra Night","hook":"Old-school contra dancing called over electronic music. No partner, no experience needed.","mission":"Tapestry Folkdance Center runs Techno Contra on the last Monday of every month. Partners rotate every dance, so your group scatters across the floor and comes back laughing. The regular Saturday contra comes with a beginner lesson.","steps":["Take the 7 bus from Washington Ave & Cedar Ave on the West Bank straight to Minnehaha & 38th St (about 30 minutes), or the Blue Line to 38th St and walk two blocks. It''s at 3748 Minnehaha Ave S.","Techno Contra: last Monday of the month (Sept 28, Oct 26, Nov 30), 8-10:30pm, $10 if you''re 18-30. Or Saturday: lesson at 7:30, dancing 8-11pm, $10 for 18-30.","Wear soft-soled, non-marking shoes and bring water.","Rule: nobody sits out more than one dance in a row."],"vibes":["active","social","weird"],"location":{"name":"Tapestry Folkdance Center","area":"Longfellow","lat":44.93463,"lng":-93.22479},"durationMin":180,"costPerPerson":10,"groupMin":2,"groupMax":8,"weirdness":4,"adventure":4,"bestTime":["evening","late"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_axman_weird_object',false,'{"id":"q_axman_weird_object","title":"Ax-Man $5 Weird Object Showdown","hook":"$5 and 20 minutes to buy the strangest thing in a store full of strange things.","mission":"Ax-Man Surplus on University Ave is a maze of lab glassware, old electronics, mannequin parts and objects nobody can identify. Everyone buys one item and pitches it on the sidewalk, and the winner becomes the group mascot.","steps":["Green Line to Snelling Ave, then a short walk to 1639 University Ave W. Open Mon-Sat 10am-6pm, Sun noon-5pm.","$5 cap, 20 minutes, split up.","Outside, everyone gives a 30-second pitch: what it is, what it''s for, why the group needs it.","Vote. The winning object becomes the group mascot and comes on every quest."],"vibes":["weird","competitive","creative"],"location":{"name":"Ax-Man Surplus","area":"Midway, St. Paul","lat":44.95606,"lng":-93.16932},"durationMin":75,"costPerPerson":5,"groupMin":2,"groupMax":6,"weirdness":5,"adventure":2,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_bins_costume_draft',false,'{"id":"q_bins_costume_draft","title":"$10 Costume From the Bins","hook":"Pay-by-the-pound thrift bins, $10 each, and you''re building someone else''s Halloween costume.","mission":"The Goodwill Outlet in St. Paul sells everything by the pound out of big blue bins. Draw a friend and a theme, dig for 30 minutes, then hold a sidewalk runway.","steps":["Green Line to Fairview Ave, then about 3 blocks north to 553 Fairview Ave N. Call 651-379-5909 for hours; weekday afternoons are calmer.","Draw a name and a theme from a hat: ''1998 dad at a Twins game'', ''Nordic villain'', ''lost tourist''.","$10 and 30 minutes to build that person''s costume. When staff roll out fresh bins, wait for their go signal before digging.","Outside, everyone layers their costume over their clothes and walks the sidewalk runway. Group votes; the winner is Halloween-approved (wash it first)."],"vibes":["creative","weird","competitive","social"],"location":{"name":"Goodwill Outlet St. Paul","area":"Midway, St. Paul","lat":44.95829,"lng":-93.1781},"durationMin":90,"costPerPerson":10,"groupMin":2,"groupMax":6,"weirdness":4,"adventure":3,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_fetus_blind_record_swap',false,'{"id":"q_fetus_blind_record_swap","title":"Blind Record Swap at the Electric Fetus","hook":"$10 to buy a used record or CD for a friend, based on vibes alone.","mission":"The Electric Fetus has been Minneapolis''s record store since 1968, and Prince shopped there. Everyone draws a name and picks music for that person without asking a single question, then you listen back to back.","steps":["Take the 2 bus along Franklin or bike about 15 minutes to 2000 4th Ave S.","Draw names. $10 and 30 minutes to find a used record or CD for your person. No asking what they like.","Keep it in the bag until you''re back at someone''s place.","Play one track from each pick. The receiver guesses why they got it."],"vibes":["creative","social","chill"],"location":{"name":"Electric Fetus","area":"Whittier / Phillips","lat":44.96238,"lng":-93.2705},"durationMin":75,"costPerPerson":10,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":1,"bestTime":["afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_streetcar_after_dark',false,'{"id":"q_streetcar_after_dark","title":"Streetcar Named Expire","hook":"A 100-year-old streetcar, dark woods between two lakes, and scares that get worse as the night goes on.","mission":"The Minnesota Streetcar Museum runs restored trolleys between Lake Harriet and Bde Maka Ska, and for Halloween it runs them at night. Streetcar Named Expire is Oct 24 for $5; Graveyard Ghost Stories by the cemetery is Oct 17.","steps":["E Line from University Ave to Sheridan & 43rd St (about 45 minutes from campus), then walk about 5 minutes east to Linden Hills Station at Queen Ave S and W 42nd St.","Pick your night: Streetcar Named Expire, Sat Oct 24, 7-10pm, $5 (or a $12 Fright Pass) and no reservations; or Graveyard Ghost Stories, Sat Oct 17, 8:30pm, $23 with a ticket.","Come in costume. Whoever screams first buys tacos after.","Cheaper daytime version: regular rides on October weekends, 1-4pm. Cards only, no cash."],"vibes":["weird","social","late-night"],"location":{"name":"Como-Harriet Streetcar (Linden Hills Station)","area":"Linden Hills","lat":44.92462,"lng":-93.3111},"durationMin":90,"costPerPerson":5,"groupMin":2,"groupMax":6,"weirdness":4,"adventure":3,"bestTime":["evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_quaking_bog_gold',false,'{"id":"q_quaking_bog_gold","title":"Gold Tamaracks at the Quaking Bog","hook":"A floating boardwalk into a real bog inside city limits, where pine-looking trees turn gold for about two weeks.","mission":"The Quaking Bog in Theodore Wirth Park is a tamarack bog you walk into on a floating boardwalk. In mid-to-late October the tamaracks turn bright yellow right before they drop their needles.","steps":["Bike about 40 minutes, or take transit about 50 minutes (Green Line downtown, then a bus out Glenwood Ave), to Theodore Wirth Pkwy & Glenwood Ave. The lot is on the west side of the parkway across from Birch Pond.","Follow the signs along the switchback trails to the bog.","On the floating boardwalk, stand still and feel it shift as people walk past. Everyone picks the brightest gold tamarack; vote on the way out.","Look for pitcher plants, which eat bugs. Stay on the boardwalk (the bog is fragile) and wear shoes that can get wet."],"vibes":["outdoors","weird","chill"],"location":{"name":"Quaking Bog (Theodore Wirth Park)","area":"Theodore Wirth Park","lat":44.973,"lng":-93.32835},"durationMin":90,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":3,"bestTime":["morning","afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_marathon_sign_squad',false,'{"id":"q_marathon_sign_squad","title":"Summit Ave Sign Squad","hook":"Make the dumbest poster you can and get 10 marathon runners to high-five it.","mission":"The Twin Cities Marathon climbs Summit Avenue on Sunday, Oct 4, right where runners are hurting most. Funny signs and loud strangers genuinely help, it''s free, and it only happens once a year.","steps":["Night before: poster board, markers, bad puns.","Bike about 20 minutes to Summit Ave & Cretin Ave in St. Paul. The first marathoners come through Summit around 9:45am.","Bring a cowbell. Cheer runners by the names on their bibs.","Goal: 10 high-fives from the curb. Don''t cross the course, and don''t shout mileage unless you''re sure."],"vibes":["social","outdoors","weird","active"],"location":{"name":"Summit Ave & Cretin Ave (marathon course)","area":"Mac-Groveland / St. Thomas","lat":44.94129,"lng":-93.19196},"durationMin":150,"costPerPerson":5,"groupMin":2,"groupMax":8,"weirdness":3,"adventure":2,"bestTime":["morning"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_umn_apple_bracket',false,'{"id":"q_umn_apple_bracket","title":"UMN Apple Bracket","hook":"The U invented the Honeycrisp. Blind-taste every U apple you can find and crown a champion.","mission":"The University of Minnesota has released 29 apple varieties, including Honeycrisp, SweeTango and Zestar!. Buy one of each you can find at the St. Paul Farmers'' Market in peak apple season and run a blind bracket.","steps":["Green Line to Union Depot. The St. Paul Farmers'' Market (290 E 5th St) is a block away and runs Sat 7am-1pm and Sun 8am-1pm.","Buy one of every U-bred apple you can find. In fall, look for Honeycrisp, SweeTango, Haralson, Frostbite, Sweet Sixteen and, by mid-October, SnowSweet.","Slice and number them. One person holds the key.","Head-to-head blind bracket until there''s a champion. Reveal the key and see if the Honeycrisp loyalists held up."],"vibes":["food","competitive","outdoors"],"location":{"name":"St. Paul Farmers'' Market (Lowertown)","area":"Lowertown, St. Paul","lat":44.94961,"lng":-93.08509},"durationMin":90,"costPerPerson":6,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":2,"bestTime":["morning"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_boba_blind_bracket',false,'{"id":"q_boba_blind_bracket","title":"Eat Street Boba Bracket","hook":"Same drink at three shops, cups labeled A, B and C, one clear winner.","mission":"Three boba spots sit within a few blocks of each other on Nicollet''s Eat Street. Kung Fu Tea is the one you can already get in Dinkytown, so it''s the control. Order the exact same drink at all three and taste them blind.","steps":["Green Line downtown, then the 18 bus down Nicollet. Hit Kung Fu Tea (2532 Nicollet Ave, sharing space with Jasmine Deli), Lu''s Sandwiches (2624 Nicollet) and Niko Niko Boba inside Eat Street Crossing (2819 Nicollet).","Buy one of the same drink at each shop for the group to share, like classic milk tea, 50% sugar, regular boba. Ask for extra cups.","One person pours and labels the cups A, B and C. Everyone else tastes blind and ranks.","Reveal. If the Dinkytown control wins, you all just wasted a bus ride; whoever ranked it first buys the next round."],"vibes":["food","competitive","social"],"location":{"name":"Kung Fu Tea (Eat Street)","area":"Whittier","lat":44.95626,"lng":-93.27818},"durationMin":75,"costPerPerson":8,"groupMin":2,"groupMax":6,"weirdness":1,"adventure":1,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_milkjam_guess_the_scoop',false,'{"id":"q_milkjam_guess_the_scoop","title":"Guess the Milkjam Flavor","hook":"Order the flavor you''d never pick, pass cups blind, and guess what everyone got.","mission":"Milkjam Creamery in Lyn-Lake changes its flavor lineup regularly, and the flavors are strange enough that guessing them is genuinely hard. September''s included coffee-cardamom with baklava, mango with rose-petal toffee, and a vegan date shortbread.","steps":["Bike the Greenway to Lyndale and ride a block north to 2743 Lyndale Ave S. Open 5-10pm weekdays, noon-10pm weekends.","Go to the counter one at a time while everyone else waits outside. Order the flavor you''d be least likely to pick and keep it to yourself.","Pass cups around and guess every flavor off the menu board. One point per correct guess.","Most points wins. Lowest score buys the next round. The lineup changes, so the game resets every time you come back."],"vibes":["food","competitive","weird"],"location":{"name":"Milkjam Creamery","area":"Lyn-Lake / Uptown","lat":44.95245,"lng":-93.2878},"durationMin":45,"costPerPerson":8,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":1,"bestTime":["evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_walker_skyline_golf',false,'{"id":"q_walker_skyline_golf","title":"Skyline Mini Golf Before It''s Gone","hook":"Artist-designed mini golf on the Walker''s roof with downtown behind every putt. It ends Oct 18.","mission":"The Walker''s Skyline Mini Golf runs on the museum''s rooftop through Oct 18. Every hole is designed by a local artist, and the skyline is the backdrop.","steps":["Book a tee time online ($12 per player, up to 8 per tee time). The Walker is open Wed-Sun 10am-5pm (Thu until 9pm) and closed Mon-Tue.","Take the E Line from University Ave to Hennepin & Groveland, about 30 minutes, right by the Walker.","Play every hole. Everyone also votes for the most unhinged one.","Highest score poses as the cherry in the Spoonbridge photo in the free Sculpture Garden after. Shoot it from the path; the sculpture sits in a pond."],"vibes":["competitive","creative","outdoors","social"],"location":{"name":"Walker Art Center","area":"Lowry Hill","lat":44.968,"lng":-93.28877},"durationMin":90,"costPerPerson":12,"groupMin":2,"groupMax":8,"weirdness":3,"adventure":1,"bestTime":["afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_art_shanty_village',false,'{"id":"q_art_shanty_village","title":"Art Shanty Village on a Frozen Lake","hook":"Walk out onto frozen Lake Harriet to a pop-up town of artist-built shanties.","mission":"Every winter Art Shanty Projects builds a temporary village of strange, interactive shanties on the ice: dance parties, games, performances. The 2027 run is weekends Jan 16 to Feb 7.","steps":["E Line to 39th St & Sheridan, then a half-mile walk to the lake near the Bandshell.","Weekends, 10am-4pm in past years. Suggested donation $10-20, nobody gets turned away.","Rule: everyone takes part in at least one shanty''s activity instead of just watching.","Vote on the best shanty on the walk off the ice. Follow the organizers'' ice guidance."],"vibes":["weird","creative","outdoors","social"],"location":{"name":"Art Shanty Projects, Lake Harriet","area":"Linden Hills / Lake Harriet","lat":44.92815,"lng":-93.30773},"durationMin":150,"costPerPerson":10,"groupMin":2,"groupMax":8,"weirdness":5,"adventure":4,"bestTime":["morning","afternoon"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_medallion_hunt_crew',false,'{"id":"q_medallion_hunt_crew","title":"Winter Carnival Treasure Hunt Crew","hook":"A real treasure hunt with a cash prize, one clue a day, and your group chat as HQ.","mission":"The Saint Paul Winter Carnival runs Jan 28 to Feb 7, 2027, and the Pioneer Press has run a medallion hunt with daily clues pointing to St. Paul-area parks since 1952. The 2026 medallion paid $15,000.","steps":["Form your crew before the carnival and set up a clue thread.","When each clue drops, everyone posts a theory. Vote on which park to search.","Search public parkland only, and don''t dig in closed or planted areas.","End nights at Rice Park (Green Line to Central) for the ice sculptures."],"vibes":["competitive","outdoors","social","weird"],"location":{"name":"Rice Park","area":"Downtown St. Paul","lat":44.94463,"lng":-93.09711},"durationMin":180,"costPerPerson":0,"groupMin":2,"groupMax":8,"weirdness":3,"adventure":4,"bestTime":["afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_first_ave_star_hunt',false,'{"id":"q_first_ave_star_hunt","title":"Find Your Star at First Ave","hook":"Hundreds of stars on a black wall, one gold one, and a hat toss to finish.","mission":"First Avenue''s outside walls are covered in stars for acts that played the club, and Prince''s is the only gold one. Bet on who made the wall, hunt, then recreate the Mary Tyler Moore hat toss on Nicollet Mall.","steps":["Green Line to Warehouse District/Hennepin Ave. First Avenue is at 701 1st Ave N.","Before looking, everyone writes down three artists they bet have a star. One point per hit.","Find Prince''s gold star for the group photo.","Walk to Nicollet Mall & 7th St, find the Mary Tyler Moore statue, and toss a beanie like she does. Film it in slow-mo."],"vibes":["social","creative","weird"],"location":{"name":"First Avenue","area":"Downtown / Warehouse District","lat":44.97826,"lng":-93.27603},"durationMin":60,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":1,"bestTime":["afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_rec_first_climb',false,'{"id":"q_rec_first_climb","title":"Free First Climb at the Rec","hook":"Your first climb at the Rec is free, gear included. Everyone gets up the wall once.","mission":"The climbing wall at the University Recreation and Wellness Center gives first-timers a free climb with shoes, harness and a safety orientation. Go as a group and yell encouragement at each other.","steps":["Check the RecWell climbing schedule, then head to the Rec at 123 Harvard St SE.","Do the required first-timer orientation together.","Everyone picks a route while the group calls out holds from the ground.","Scoring: one point for halfway, three for touching the top. Hooked? Day passes are $15."],"vibes":["active","social","competitive"],"location":{"name":"University Recreation and Wellness Center","area":"East Bank (campus)","lat":44.97567,"lng":-93.22995},"durationMin":90,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":1,"adventure":4,"bestTime":["afternoon","evening"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_wirth_first_ski_night',false,'{"id":"q_wirth_first_ski_night","title":"First Ski Night at Wirth","hook":"Rent cross-country skis, fall over together on a lit trail, and count everyone''s wipeouts.","mission":"The Trailhead in Theodore Wirth Park rents cross-country skis and has lit snowmaking loops, so you can try a real Minnesota winter sport without a car trip to a resort. Not feeling it? The sledding hill is free.","steps":["Winter only, once the trails are open (they make their own snow). Take the 7 bus from Washington Ave & Cedar Ave on the West Bank to its last stop at the Trailhead, about 40 minutes.","Rent the classic ski package plus an All-Access trail pass ($26 combo; renters must be 18+), or skip it and use the free sledding hill. No new rentals after 7pm, and rentals last 3 hours.","Ski the lit loop together. Everyone counts their own falls.","Fewest falls picks the hot chocolate spot. Most falls gets the group''s respect and nothing else."],"vibes":["active","outdoors","social"],"location":{"name":"The Trailhead (Theodore Wirth Park)","area":"Theodore Wirth Park","lat":44.99175,"lng":-93.32632},"durationMin":150,"costPerPerson":26,"groupMin":2,"groupMax":6,"weirdness":2,"adventure":4,"bestTime":["afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_bridge_sprint',false,'{"id":"q_bridge_sprint","title":"Two-Bridge Relay","hook":"Cross the river twice, pass a water bottle like a baton, and the slower team buys coffee.","mission":"A relay loop that starts at the Washington Avenue Bridge, runs up the West Bank, and comes back over the 10th Avenue Bridge. It''s about 2 miles, every handoff happens at a bridge end, and the downriver views beat your usual walk to class.","steps":["Split into two teams at the Coffman end of the Washington Ave Bridge. A water bottle is the baton.","Leg 1: cross the bridge''s upper deck to the West Bank. Leg 2: north on 19th Ave S to the 10th Ave Bridge.","Leg 3: cross the 10th Ave Bridge back to the East Bank. Leg 4: back along East River Parkway to Coffman.","Jog, don''t sprint through crowds, and stay on sidewalks and paths. Slower team buys coffee at Coffman."],"vibes":["active","competitive","outdoors","social"],"location":{"name":"Washington Avenue Bridge","area":"East Bank (campus)","lat":44.97306,"lng":-93.23991},"durationMin":45,"costPerPerson":5,"groupMin":2,"groupMax":8,"weirdness":2,"adventure":3,"bestTime":["morning","afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_dinkytown_stranger_advice',true,'{"id":"q_dinkytown_stranger_advice","title":"Stranger''s Advice Run","hook":"Ask five strangers what to do next. Then actually do it.","mission":"Crowdsource your night from Dinkytown strangers. Whatever the fifth person says, the group has to attempt.","steps":["Ask five people the same question: what should we do right now?","Write every answer down verbatim.","The fifth answer is binding, within reason and budget.","Report back on how it went."],"vibes":["weird","social","late-night"],"location":{"name":"14th & 4th St SE","area":"Dinkytown","lat":44.9814,"lng":-93.2363},"durationMin":60,"costPerPerson":10,"groupMin":2,"groupMax":4,"weirdness":5,"adventure":5,"bestTime":["afternoon","evening","late"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_rooftop_skyline_count',true,'{"id":"q_rooftop_skyline_count","title":"Skyline Window Count","hook":"Guess how many lit windows are on the IDS tower. Then argue.","mission":"From the Loring Park side, everyone guesses the number of lit windows downtown, then you sample-count one section to settle it.","steps":["Find a clear downtown view from Loring Park.","Everybody writes a guess without discussing.","Count one vertical strip together and extrapolate.","Closest guess picks the walk home route."],"vibes":["chill","weird","competitive"],"location":{"name":"Loring Park","area":"Loring Park","lat":44.9704,"lng":-93.2836},"durationMin":30,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":4,"adventure":1,"bestTime":["evening","late"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_coffee_wrongorder',true,'{"id":"q_coffee_wrongorder","title":"Wrong Order Coffee Club","hook":"Order the drink you''d never order. Finish it.","mission":"At a campus coffee shop, everybody orders the drink they are most confident they will dislike, then has to finish it.","steps":["Pick a coffee shop near campus.","Order the drink you''re most sure you''ll hate.","No dumping, no sharing, no sugar rescues.","Rate how wrong you were on a scale of 1-5."],"vibes":["food","chill","weird"],"location":{"name":"Oak Street SE","area":"East Bank","lat":44.9752,"lng":-93.2277},"durationMin":30,"costPerPerson":8,"groupMin":1,"groupMax":5,"weirdness":3,"adventure":2,"bestTime":["morning","afternoon"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_bus_stop_playlist',true,'{"id":"q_bus_stop_playlist","title":"Bus Stop Playlist Battle","hook":"One song each, chosen by the person next to you.","mission":"Build a playlist at a campus transit stop where nobody picks their own songs, then walk a full loop listening to it.","steps":["Meet at a transit shelter on campus.","Each person picks a song for the person on their right.","Queue them in order and share earbuds or a speaker.","Walk a loop of campus without skipping anything."],"vibes":["chill","social","creative"],"location":{"name":"Coffman Union","area":"East Bank","lat":44.9727,"lng":-93.2353},"durationMin":45,"costPerPerson":0,"groupMin":2,"groupMax":6,"weirdness":3,"adventure":1,"bestTime":["afternoon","evening","late"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_st_anthony_stair_ladder',true,'{"id":"q_st_anthony_stair_ladder","title":"St. Anthony Stair Ladder","hook":"Every staircase on the east bank. One continuous climb.","mission":"Find and climb every set of public stairs between St. Anthony Main and the university, counting steps the whole way.","steps":["Start at St. Anthony Main and head upriver.","Climb every public staircase you pass.","Count steps out loud together.","Stop when the total passes 400."],"vibes":["active","outdoors","competitive"],"location":{"name":"St. Anthony Main","area":"Marcy-Holmes","lat":44.9855,"lng":-93.2569},"durationMin":60,"costPerPerson":0,"groupMin":1,"groupMax":5,"weirdness":2,"adventure":3,"bestTime":["morning","afternoon","evening"],"indoor":false}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.quests(id,archived,content) VALUES ('q_karaoke_draft',true,'{"id":"q_karaoke_draft","title":"Karaoke Assignment Night","hook":"You don''t choose your song. Your squad does.","mission":"A karaoke night where every song is assigned by somebody else and refusing is not an option.","steps":["Find a karaoke spot with an open list.","Each person secretly assigns a song to one other person.","Reveal assignments only when you''re called up.","Score performances on commitment, not talent."],"vibes":["social","late-night","competitive","weird"],"location":{"name":"Downtown East","area":"Downtown","lat":44.9752,"lng":-93.2621},"durationMin":120,"costPerPerson":20,"groupMin":3,"groupMax":6,"weirdness":4,"adventure":4,"bestTime":["late"],"indoor":true}'::jsonb) ON CONFLICT(id) DO NOTHING;
